create function public.validate_task_status() returns trigger language plpgsql set search_path=public as $$ begin if not exists(select 1 from workspaces where id=new.workspace_id and new.status=any(workflow_states)) then raise exception 'Choose a status from this workspace workflow'; end if; return new;end $$;
create trigger task_status before insert or update on tasks for each row execute function validate_task_status();
create function public.validate_workflow() returns trigger language plpgsql set search_path=public as $$ begin if not 'Done'=any(new.workflow_states) or cardinality(new.workflow_states)<2 then raise exception 'Keep at least two states, including Done'; end if;if exists(select 1 from tasks where workspace_id=new.id and not status=any(new.workflow_states)) then raise exception 'Move existing tasks before removing their workflow state';end if;return new;end $$;
create trigger workflow_valid before update of workflow_states on workspaces for each row execute function validate_workflow();
create function public.update_retainer_usage() returns trigger language plpgsql security definer set search_path=public as $$ begin update retainers r set used=coalesce((select sum(t.minutes)/60.0 from time_entries t where t.workspace_id=r.workspace_id and t.project_id=r.project_id and t.billable and t.entry_date>=r.period and t.entry_date<(r.period+interval '1 month')),0) where r.workspace_id=coalesce(new.workspace_id,old.workspace_id) and r.project_id in (new.project_id,old.project_id);return coalesce(new,old);end $$;
create trigger retainer_time after insert or update or delete on time_entries for each row execute function update_retainer_usage();
create function public.add_workspace_member(w uuid,member_email text,member_role text) returns void language plpgsql security definer set search_path=public as $$ declare u uuid;begin if public.workspace_role(w)<>'owner' or public.workspace_role(w) is null then raise exception 'Only owners can add members';end if;if member_role not in ('member','contractor','client') then raise exception 'Choose member, contractor, or client';end if;select id into u from auth.users where lower(email)=lower(trim(member_email));if u is null then raise exception 'This person must create an account first';end if;insert into workspace_members(workspace_id,user_id,role,display_name) values(w,u,member_role,split_part(member_email,'@',1));end $$;
revoke all on function public.add_workspace_member(uuid,text,text) from public;
grant execute on function public.add_workspace_member(uuid,text,text) to authenticated;
